import BufferView from '../../viewer.mjs'

export function parse (bytes) {
  const view = new BufferView(bytes)
  const version = view.getUint16(0)
  let creationTime, modificationTime, timescale, duration
  let offset = 0

  if (version === 0) {
    creationTime = view.getUint32(4)
    modificationTime = view.getUint32(8)
    timescale = view.getUint32(12)
    duration = view.getUint32(16)
    offset = 20
  } else if (version === 1) {
    creationTime = view.getUint64(4)
    modificationTime = view.getUint64(12)
    timescale = view.getUint32(20)
    duration = view.getUint64(24)
    offset = 32
  }

  return {
    creationTime,
    modificationTime,
    timescale,
    duration,
    rate: view.getInt32(offset),
    volume: view.getInt16(offset + 4),
    matrix: view.getInt32(offset + 16, 36),
    preDefined: view.getUint32(offset + 52, 24),
    nextTrackID: view.getUint32(offset + 76)
  }
}

export function validate (value) {
  const {
    creationTime,
    modificationTime,
    timescale,
    duration,
    rate,
    volume,
    matrix,
    preDefined,
    nextTrackID
  } = value

  if (
    typeof creationTime !== 'number' ||
    typeof modificationTime !== 'number' ||
    typeof timescale !== 'number' ||
    typeof duration !== 'number' ||
    typeof rate !== 'number' ||
    typeof volume !== 'number' ||
    typeof nextTrackID !== 'number'
  ) {
    throw new Error('`mvhd` Invalid value')
  }

  if (!Array.isArray(matrix) || matrix.length !== 9 || matrix.some(byte => byte < 0 || byte > 4294967295)) {
    throw new Error('`mvhd` matrix is invalid')
  }

  if (!Array.isArray(preDefined) || preDefined.length !== 6 || preDefined.some(byte => byte < 0 || byte > 4294967295)) {
    throw new Error('`mvhd` preDefined is invalid')
  }
}

export function encode (value) {
  const {
    creationTime,
    modificationTime,
    timescale,
    duration,
    rate,
    volume,
    matrix,
    preDefined,
    nextTrackID
  } = value

  const version = creationTime > 4294967295 || modificationTime > 4294967295 || duration > 4294967295 ? 1 : 0
  const view = new BufferView((version === 1 ? 32 : 20) + 80)
  view.setUint16(0, version)
  view.setUint16(2, 0)

  let offset = 0
  if (version === 0) {
    view.setUint32(4, creationTime)
    view.setUint32(8, modificationTime)
    view.setUint32(12, timescale)
    view.setUint32(16, duration)
    offset = 20
  } else {
    view.setBigUint64(4, creationTime)
    view.setBigUint64(12, modificationTime)
    view.setUint32(20, timescale)
    view.setBigUint64(24, duration)
    offset = 32
  }

  view.setInt32(offset, rate)
  view.setInt16(offset + 4, volume)
  for (let i = 0; i < 10; i++) {
    view.setUint8(offset + 6 + i, 0)
  }

  for (let i = 0; i < 9; i++) {
    const num = matrix[i]
    view.setInt32(offset + 16 + (i * 4), num)
  }

  for (let i = 0; i < 6; i++) {
    const num = preDefined[i]
    view.setUint32(offset + 52 + (i * 4), num)
  }

  view.setUint32(offset + 76, nextTrackID)
  return view.getUint8(0, view.byteLength, true)
}
